g=[[0]*30 for _ in range(30)]
pat=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22,29]
for bi,r0 in enumerate(starts):
  for bj,c0 in enumerate(starts):
    for u in range(min(5,30-r0)):
      for v in range(min(5,30-c0)):
        g[r0+u][c0+v]=4 if (u in (0,4) or v in (0,4) or bi>=4 or bj>=4) else pat[bi][bj]
# Add horizontal connections between matching non-dominant symbols, and vertical equivalents.
for r, color, gapcols in [(3,3,[6,7,13,14,20,21]),(17,3,[6,7,13,14,20,21]),(10,8,[13,14]),(24,8,[13,14])]:
  for c in gapcols: g[r][c]=color
for c,color,gaprows in [(3,3,[6,7,13,14]),(24,3,[6,7,13,14]),(10,8,[13,14,20,21]),(17,8,[13,14,20,21])]:
  for r in gaprows: g[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in g))

